INSERT INTO listening_lesson (id, lesson_no, title, audio_key, duration_ms, sort_order) VALUES ('listen-13', 13, '第13課 听力训练', 'listening/listening-lesson-13.mp3', 133677, 0);
INSERT INTO listening_section (id, lesson_id, section_no, kind, instruction, audio_start_ms, audio_end_ms, example_prompt, example_answer) VALUES ('lsn13-s1', 'listen-13', 1, 'tf', '听录音，根据录音中的内容判断对错。对的画（○），错的画（×）。', 14045, 75023, '', '');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn13-s1-q1', 'lsn13-s1', 1, '鍵はテーブルの上にあります。', '[]'::jsonb, '×');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn13-s1-q2', 'lsn13-s1', 2, 'この夏休みは海へ行きます。', '[]'::jsonb, '○');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn13-s1-q3', 'lsn13-s1', 3, '女の人は何も買いませんでした。', '[]'::jsonb, '○');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn13-s1-l1', 'lsn13-s1', 1, 'A', 14345, 16789, 'お母さん、鍵は？', 'A：妈妈，钥匙呢？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn13-s1-l2', 'lsn13-s1', 2, 'B', 17024, 20355, 'え？テーブルの上だよ。', 'B：诶？在桌子上啊。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn13-s1-l3', 'lsn13-s1', 3, 'A', 21086, 23834, 'ん？テーブルの上には何もないよ。', 'A：嗯？桌子上什么都没有啊。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn13-s1-l4', 'lsn13-s1', 4, 'B', 24423, 26054, 'おかしいね。', 'B：奇怪了。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn13-s1-l5', 'lsn13-s1', 5, 'A', 32282, 37554, '暑いですね。', 'A：真热啊。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn13-s1-l6', 'lsn13-s1', 6, 'B', 38225, 42566, '本当ですね。この夏休み、どこかへ行きますか。', 'B：是啊。这个暑假要去哪里吗？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn13-s1-l7', 'lsn13-s1', 7, 'A', 43746, 45426, '涼しいところがいいですね。', 'A：想去凉快的地方。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn13-s1-l8', 'lsn13-s1', 8, 'B', 46275, 49971, 'じゃ、海がいいですね。', 'B：那海边不错。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn13-s1-l9', 'lsn13-s1', 9, '女', 56182, 61380, 'ただいま。', '女：我回来了。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn13-s1-l10', 'lsn13-s1', 10, '男', 61381, 64693, 'お帰りなさい。どこへ行きましたか。', '男：你回来了。去哪儿了？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn13-s1-l11', 'lsn13-s1', 11, '女', 65077, 65707, 'デパート。', '女：百货商店。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn13-s1-l12', 'lsn13-s1', 12, '男', 66166, 67276, '何か買いましたか？', '男：买了什么吗？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn13-s1-l13', 'lsn13-s1', 13, '女', 68040, 74323, 'ううん。安い商品はいくつかありましたが、ほしいものはありませんでした。', '女：没有。便宜的东西倒是有几样，但没有我想要的。');
INSERT INTO listening_section (id, lesson_id, section_no, kind, instruction, audio_start_ms, audio_end_ms, example_prompt, example_answer) VALUES ('lsn13-s2', 'listen-13', 2, 'text', '听录音，根据录音中的内容回答问题（用日语输入，标点可省略）。背景：男生和女生在对话。', 90096, 127189, '', '');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn13-s2-q1', 'lsn13-s2', 1, '男の人は、この後、何がありますか。', '[]'::jsonb, '会議があります|会議|会議です');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn13-s2-q2', 'lsn13-s2', 2, '男の人はどこかへ行きましたか。', '[]'::jsonb, 'はい、コンビニに行きました|コンビニに行きました|はいコンビニに行きました');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn13-s2-q3', 'lsn13-s2', 3, '男の人は今、時間がありますか。', '[]'::jsonb, 'いいえ、ありません|いいえ|ありません');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn13-s2-q4', 'lsn13-s2', 4, '男の人はいつから時間がありますか。', '[]'::jsonb, '10時10分からです|10時10分から|10時10分');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn13-s2-l1', 'lsn13-s2', 1, '男', 90396, 91476, 'おはようございます。', '男：早上好。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn13-s2-l2', 'lsn13-s2', 2, '女', 92363, 93443, 'おはようございます。どこかへ行きましたか。', '女：早上好。你去哪儿了吗？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn13-s2-l3', 'lsn13-s2', 3, '男', 93444, 95256, 'いいえ、どうして？', '男：没有，怎么了？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn13-s2-l4', 'lsn13-s2', 4, '女', 96714, 99694, 'さっき、探しましたが、いませんでしたよ。', '女：刚才我找过你，你不在。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn13-s2-l5', 'lsn13-s2', 5, '男', 99695, 104328, 'あ、ちょっとあそこのコンビニに行きました。何かありますか。', '男：啊，我去了一下那边的便利店。有事吗？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn13-s2-l6', 'lsn13-s2', 6, '女', 104769, 109774, 'あのう、ちょっと質問がありますけど、今、お時間、大丈夫ですか。', '女：那个，我有个问题想问，你现在有时间吗？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn13-s2-l7', 'lsn13-s2', 7, '男', 110063, 114491, '今はちょっと…もうすぐ会議ですから。', '男：现在有点……马上要开会了。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn13-s2-l8', 'lsn13-s2', 8, '女', 114864, 116361, 'そうですか。', '女：这样啊。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn13-s2-l9', 'lsn13-s2', 9, '男', 116632, 123267, 'この後は？会議は10時までなので、10時10分とかはどうですか。', '男：之后呢？会议开到10点，10点10分怎么样？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn13-s2-l10', 'lsn13-s2', 10, '女', 123801, 126489, 'はい、大丈夫です。ありがとうございます。', '女：好，可以。谢谢。');
